def describe_existing_quizzes(apps, schema_editor):
    """Quizzes criados antes dos tipos de pergunta: preserva-os como estão (4 alternativas)."""
    Quiz = apps.get_model("quizzes", "Quiz")
    Question = apps.get_model("quizzes", "Question")
    Option = apps.get_model("quizzes", "Option")
    for question in Question.objects.all():
        if any(marker in question.prompt.lower() for marker in CLOZE_MARKERS):
            question.kind = "fill_blank"
            question.save(update_fields=["kind"])
    for quiz in Quiz.objects.all():
        questions = Question.objects.filter(quiz=quiz)
        first = questions.order_by("order").first()
        quiz.options_per_question = Option.objects.filter(question=first).count() if first else 4
        plan = {}
        for kind in questions.values_list("kind", flat=True):
            plan[kind] = plan.get(kind, 0) + 1
        quiz.config = {"plan": plan, "requested": questions.count(), "legacy": True}
        quiz.save(update_fields=["options_per_question", "config"])


